{
  std::lock_guard lock(_mutex);
  _has_been_notified = true;
  _cv.notify_one();
}

void notification_channel::release_notifier()
{
  std::lock_guard lock(_mutex);
  _n_active_notifiers--;
  if (_n_active_notifiers == 0) { _cv.notify_all(); }
}

